import React, { useState } from 'react';
// import { apiRequest } from '@/lib/queryClient';
import './css_files/analyzer.css'; // Ensure this path is correct

const TwitterAnalyzer = () => {
  const [userInput, setUserInput] = useState('');
  const [sentiment, setSentiment] = useState(null);
  const [isLoading, setIsLoading] = useState(false);

  const handleInputChange = (e) => {
    setUserInput(e.target.value);
    e.target.style.height = 'auto';
    e.target.style.height = `${e.target.scrollHeight}px`;
  };

  const analyzeSentiment = async () => {
    if (!userInput.trim()) return;
    setIsLoading(true);
    try {
      const response = await apiRequest('POST', '/api/predictTweet', { text: userInput });
      const data = await response.json();
      setSentiment(data);
    } catch (error) {
      console.error('Error:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const getCompoundMarkerPosition = (score) => {
    return ((score + 1) / 2) * 100;
  };

  return (
    <div className="analyzer-container">
      <div className="analyzer-card">
        <h2 className="analyzer-heading">Twitter Sentiment Analysis</h2>
        <p className="analyzer-subheading">Analyze the sentiment of any tweet or text</p>

        <div className="analyzer-content">
          <div className="input-section">
            <h3>Enter Tweet</h3>
            <textarea
              value={userInput}
              onChange={handleInputChange}
              placeholder="Type your tweet here..."
            />
            <button
              className={`analyze-btn ${isLoading ? 'loading' : ''}`}
              onClick={analyzeSentiment}
              disabled={isLoading}
            >
              {isLoading ? (
                <>
                  <span className="loading-spinner"></span>
                  Analyzing...
                  <span className="loading-wave"></span>
                </>
              ) : 'Analyze'}
            </button>
          </div>

          <div className="result-section">
            <h3>Analysis Results</h3>

            {isLoading && (
              <div className="loading-results">
                <div className="spinner"></div>
                <p>Analyzing sentiment...</p>
              </div>
            )}

            {!isLoading && !sentiment && (
              <div className="no-result">
                <svg className="empty-icon" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M9.75 17L9 20l-1 1h8l-1-1-.75-3M3 13h18M5 17h14a2 2 0 002-2V5a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />
                </svg>
                <p>Analysis results will appear here</p>
              </div>
            )}

            {!isLoading && sentiment && (
              <div>
                <div style={{ textAlign: 'center' }}>
                  <div className={`sentiment-badge ${sentiment.sentiment.toLowerCase()}`}>
                    {sentiment.sentiment}
                  </div>
                </div>

                <div className="score-details">
                  <h4>Sentiment Scores:</h4>

                  <div className="score-item">
                    <span>Positive</span>
                    <div className="score-bar">
                      <div className="score-fill positive" style={{ width: `${sentiment.vader_score.pos * 100}%` }}></div>
                    </div>
                    <span className="score-value">{(sentiment.vader_score.pos * 100).toFixed(1)}%</span>
                  </div>

                  <div className="score-item">
                    <span>Neutral</span>
                    <div className="score-bar">
                      <div className="score-fill neutral" style={{ width: `${sentiment.vader_score.neu * 100}%` }}></div>
                    </div>
                    <span className="score-value">{(sentiment.vader_score.neu * 100).toFixed(1)}%</span>
                  </div>

                  <div className="score-item">
                    <span>Negative</span>
                    <div className="score-bar">
                      <div className="score-fill negative" style={{ width: `${sentiment.vader_score.neg * 100}%` }}></div>
                    </div>
                    <span className="score-value">{(sentiment.vader_score.neg * 100).toFixed(1)}%</span>
                  </div>

                  <div className="score-item" style={{ marginTop: '1.5rem' }}>
                    <span>Compound</span>
                    <div className="score-bar compound">
                      <div className="score-fill compound" style={{ left: `${getCompoundMarkerPosition(sentiment.vader_score.compound)}%` }}></div>
                    </div>
                    <div className="compound-labels">
                      <span>-1.0</span>
                      <span>0</span>
                      <span>+1.0</span>
                    </div>
                    <span className="score-value">{sentiment.vader_score.compound.toFixed(3)}</span>
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="analyzer-footer">
          <p>Powered by machine learning • VADER sentiment analysis</p>
        </div>
      </div>
    </div>
  );
};

export default TwitterAnalyzer;
